// JavaScript mode, Run once for all items
return items.map((it, idx) => {
  const bin = it.binary || {};
  // prefer "data" key if present
  const key = bin.data ? 'data' : Object.keys(bin)[0];
  if (!key) throw new Error(`Item ${idx}: no binary found.`);

  const b64 = bin[key].data;
  if (!b64) throw new Error(`Item ${idx}: binary[${key}].data missing.`);

  const html = Buffer.from(b64, 'base64').toString('utf8');

  // keep some metadata if you want
  const fileName = bin[key].fileName || `item_${idx}.html`;

  return {
    json: { html, fileName },
    // (optional) keep the original binary alongside:
    // binary: it.binary
  };
});

// Input from previous node is plain TEXT in json.Main
const raw = $json.Main || $json.html || '';
// Optional: strip [link] artifacts the HTML Extractor adds
const text = raw.replace(/\s*\[[^\]]+\]/g, '').replace(/\s+/g, ' ').trim();

return { json: { text } };

// --- 1) Pull model text robustly (Gemini + fallbacks) ---
function collectText(o) {
  const pieces = [];

  // Gemini "candidates" shape
  const cands = Array.isArray(o?.candidates) ? o.candidates : [];
  for (const c of cands) {
    const parts = c?.content?.parts || [];
    for (const p of parts) if (typeof p?.text === 'string') pieces.push(p.text);
  }

  // Occasional alternate shapes
  const altParts =
    (o?.content?.parts) ||
    (o?.gemini?.content?.parts) ||
    (Array.isArray(o?.[0]?.candidates) ? o?.[0]?.candidates?.[0]?.content?.parts : []) ||
    [];
  for (const p of altParts) if (typeof p?.text === 'string') pieces.push(p.text);

  if (typeof o?.output_text === 'string') pieces.push(o.output_text);
  if (typeof o?.text === 'string') pieces.push(o.text);

  return pieces.join('\n');
}

const raw = collectText($json);

// --- 2) Find a JSON object with "controls" ---
function pickControlsJson(s) {
  s = String(s || '');

  // a) fenced ```json ... ``` blocks
  const blocks = [];
  const reFence = /```(?:json)?\s*([\s\S]*?)\s*```/gi;
  let m;
  while ((m = reFence.exec(s)) !== null) blocks.push(m[1].trim());
  const byControls = (a, b) => (b.includes('"controls"') - a.includes('"controls"'));
  for (const b of blocks.sort(byControls)) {
    try {
      const o = JSON.parse(b);
      if (o && (Array.isArray(o.controls) || o.controls)) return o;
    } catch {}
  }

  // b) any {...} blob (last resort)
  const objs = s.match(/{[\s\S]*?}/g) || [];
  for (const cand of objs.sort(byControls)) {
    try {
      const o = JSON.parse(cand);
      if (o && (Array.isArray(o.controls) || o.controls)) return o;
    } catch {}
  }

  // c) top-level array of controls
  const arrs = s.match(/\[[\s\S]*?\]/g) || [];
  for (const cand of arrs) {
    try {
      const a = JSON.parse(cand);
      if (Array.isArray(a) && a.length && (a[0].control_name || a[0].control)) {
        return { controls: a };
      }
    } catch {}
  }

  return null;
}

const parsed = pickControlsJson(raw);
if (!parsed) {
  throw new Error('Could not find a JSON object with "controls" in model output.');
}

// --- 3) Normalize rows (keep steps as STRING) ---
const controls = Array.isArray(parsed.controls) ? parsed.controls : [];
const rows = controls.map(c => ({
  control: String(c.control_name ?? c.control ?? '').trim(),
  description: String(c.description ?? '').trim(),
  category: String(c.category ?? '').trim(),
  severity: String(c.severity ?? '').trim(),
  ui_path: String(c.ui_path ?? '').trim(),
  // steps can be string or array from the model; keep a single string
  steps: Array.isArray(c.steps)
    ? c.steps.map(s => String(s)).filter(Boolean).join(' ')
    : String(c.steps ?? '').trim(),
  needs_human: Boolean(c.needs_human),
})).filter(r => r.control && r.description && r.category && r.severity);

// --- 4) Return ---
return { json: { rows } };

const resp = $json;
const cand  = resp?.candidates?.[0] ?? resp?.response?.candidates?.[0];
const parts = Array.isArray(cand?.content?.parts) ? cand.content.parts : [];
let raw = '';
for (const p of parts) {
  if (p && typeof p.text === 'string') raw += p.text;
  else if (p?.inlineData?.data) {
    try { raw += Buffer.from(p.inlineData.data, 'base64').toString('utf8'); } catch {}
  }
}
if (!raw) throw new Error('Empty Gemini response');

let parsed;
try { parsed = JSON.parse(raw); }
catch {
  const m = raw.match(/```(?:json)?\s*([\s\S]*?)\s*```/i) || raw.match(/{[\s\S]*}/);
  if (!m) throw new Error('Not valid JSON');
  parsed = JSON.parse(m[1] || m[0]);
}
return { controls: Array.isArray(parsed?.controls) ? parsed.controls : [] };

